/*!40000 ALTER TABLE `propiedad` DISABLE KEYS */;
INSERT INTO `propiedad` VALUES (1,0,238.8,'0005',1,'Casa de dos niveles con 3 locales comerciales con gran potencial de renta, 4 habitaciones amplias y cómodas, 3 baños bien distribuidos, sala-comedor espaciosa, cocina funcional, patio de ropas. Vista privilegiada al parque principal de Guatavita.','Oportunidad Única en el Centro de Guatavita','Guatavita','disponible'),(1,0,51.23,'0008',2,'Habitación principal con baño privado y vestier, habitación secundaria ideal para familia o estudio, sala-comedor con excelente iluminación, cocina integral con horno y barra americana, zona de ropas independiente, balcón con vista exterior, parqueadero incluido. Amenidades del conjunto: piscina, zona BBQ, salón de eventos, gimnasio, ascensor en la torre.','Oportunidad de Apartamento en Tocancipá ','Tocancipá','disponible'),(1,0,999,'0012',3,'Casa de tres niveles con espacios independientes. Primer piso: 4 habitaciones, sala y comedor, 2 baños, patio de ropas, cocina. Segundo piso: 4 habitaciones, 2 baños, cocina, sala comedor. Tercer piso: sala de lavado, 1 baño, 1 habitación, terraza cubierta. Ideal para inversión o vivienda familiar.','Venta de Casa en Bogotá ','Bogotá','disponible'),(1,0,1.725,'0013',4,'Servicios disponibles: agua y energía eléctrica. Ubicación estratégica: colinda con la vía principal del municipio, con fácil acceso y excelente conectividad. Vista privilegiada al embalse, ideal para disfrutar de la tranquilidad y la naturaleza. Asesoría legal incluida para una compra segura.','Lote en Venta en Guatavita ','Guatavita','disponible'),(1,0,56.1,'0014',5,'Servicios disponibles: acueducto, energía eléctrica, alcantarillado. Aprobación para construcción de vivienda de hasta 4 niveles. Ubicación estratégica en un sector residencial exclusivo y rodeado de naturaleza. Asesoría legal incluida para una compra segura.','¡Oportunidad Única! Lote en La Vega ','La Vega','disponible'),(1,0,33.455,'0018',6,'Construcción campestre con 3 habitaciones, sala comedor, cocina, 1 baño. Servicios y comodidades: 2 nacimientos de agua propios, pozo séptico. Perfecta para descanso, inversión o proyectos agropecuarios. Asesoría legal incluida para una compra segura.','Finca en Guatavita ','Guatavita','disponible'),(1,0,12125.1,'0022',7,'Acceso privado con servidumbre. Nacimiento de agua en el lote. Punto de agua de acueducto veredal. Vista espectacular y ambiente de tranquilidad inigualable. Apto para: construcción de vivienda campestre, proyectos agrícolas o ganaderos, inversión en finca raíz. Asesoría legal incluida para una compra segura.','Lote en Guatavita con Hermoso Paisaje ','Guatavita','disponible'),(1,0,10976.1,'0023',8,'Cabaña campestre con 1 habitación, sala comedor, cocina, baño privado. Servicios públicos disponibles: acueducto veredal, nacimiento de agua, energía eléctrica. Accesos y entorno natural: servidumbre privada de acceso. Espacio ideal para descanso, agricultura o inversión. Asesoría legal incluida para una compra segura.','Lote con Cabaña en el Campo','Guatavita','disponible'),(1,164,10878,'0026',9,'Vivienda amplia y funcional: 4 habitaciones, sala y comedor, cocina, estudio, patio de ropas. Servicios públicos disponibles: acueducto, alcantarillado, energía eléctrica. Accesos y entorno natural: ubicación estratégica en Tocancipá. Ideal para vivienda, inversión o proyectos agropecuarios. Asesoría legal incluida para una compra segura. ','Venta de Finca con Construcción en Tocancipá ','Tocancipá','disponible'),(1,220,449,'0029',10,'Vivienda amplia y funcional: 7 habitaciones, 3 baños, 2 cocinas, patio de ropas. Segundo nivel independiente, ideal para renta o doble vivienda. Ubicación estratégica: zona tranquila y de alta valorización en Tocancipá. Servicios incluidos: agua, luz, alcantarillado. Asesoría legal para una compra segura.','Venta de Casa Lote en Tocancipá ','Tocancipá','disponible'),(1,0,3770,'0030',11,'Construcciones en el predio: casa principal de 2 niveles con 2 habitaciones, sala-comedor, cocina, baño y chimenea. Chalet de 2 niveles con 1 habitación, sala-comedor, cocina y baño. 3 cabañas de madera perfectas para alquiler o descanso. Zona BBQ campestre ideal para reuniones familiares. Parqueadero amplio. Ubicación privilegiada: colinda con la vía principal de acceso a Guatavita. Servicios incluidos: agua, luz, pozo séptico. Asesoría legal para una compra segura.','Venta de Finca en Guatavita ','Guatavita','disponible'),(1,0,19200,'0031',12,'Abundante agua: acueducto veredal, 2 reservorios, 1 nacimiento de agua propio. Accesibilidad: cuenta con servidumbre vehicular. Uso del suelo: apta para construcción de vivienda campestre, perfecta para proyectos agrícolas y ganaderos. Asesoría legal para una compra segura.','Venta de Finca en Guatavita','Guatavita','disponible'),(1,0,80,'0036',13,'2 habitaciones, la principal con baño privado. 1 estudio perfecto para home office. Sala y comedor independientes. Cocina funcional y zona de lavandería. Parqueadero privado. Vigilancia 24/7. Ubicación estratégica en Lisboa, Nuevo Contry. Cerca a la Clínica El Bosque, centros comerciales y bancos. Zona con acceso a comercio, transporte y áreas recreativas. Asesoría legal para una compra segura.','Lindo Apartamento en Bogotá','Bogotá','disponible'),(1,0,300,'0037',14,'4 habitaciones con closets. 3 baños, principal con baño privado. Sala con chimenea y sala de estar. Balcón con vista al jardín. Altillo y garaje privado. Cocina integral. Ubicación privilegiada con vista al jardín.','Hermosa Casa en Guasca','Guasca','disponible'),(1,145,5495,'0038',15,'Construcción de dos niveles + altillo. 3 habitaciones con baño y clósets. Chimenea para un ambiente acogedor. Sala y comedor amplios. Cocina espaciosa. Estudio ideal para home office. Jacuzzi para disfrutar momentos de relajación. Área de ropas y calentador a gas. Kiosco BBQ para reuniones al aire libre. Garaje para 2 vehículos. Servicios: acueducto y alcantarillado, energía eléctrica.','Venta de Hermosa Finca con Vista al Embalse en Guatavita ','Guatavita','disponible'),(1,300,108000,'0041',16,'1 habitación, baño social. Segundo nivel y altillo: 4 habitaciones, 4 baños, casa del árbol. Zonas sociales y adicionales: cocina abierta con isla, sala con chimenea y comedor, área de ropas y depósito, kiosco, BBQ y horno asador, espacio para galpón y huerta casera, amplias zonas verdes. Servicios y accesibilidad: agua, luz y alcantarillado, 2 reservorios de agua, entrada vehicular.','Finca con Vista al Embalse de Guatavita','Guatavita','disponible'),(1,199,650,'0042',17,'4 habitaciones amobladas, 4 baños, cocina integral, zona de lavandería en solar, espacio para parqueadero, amplia zona verde. Predio encerrado por pared en bloque.','Casa Lote en Venta – Gachancipá','Gachancipá','disponible'),(1,0,615.5,'0043',18,'Proyecto Villa del Mar – Conjunto Cerrado. Beneficios del conjunto cerrado: piscinas, canchas de tenis, club house con espacios de recreación, senderos peatonales, parqueaderos privados.','Lote Esquinero en Venta – Carmen de Apicalá','Carmen de Apicalá','disponible'),(1,0,12860,'0045',19,'Ubicación rodeada de naturaleza y tranquilidad. 1 nacimiento de agua y 1 punto de agua veredal. Servicios de energía eléctrica y pozo séptico. Acceso directo a la vía veredal.','Finca con Vivienda Campestre en Guatavita','Guatavita','disponible'),(1,0,38000,'0046',20,'Zona tranquila con paisaje espectacular. Colindancia con el Río Aves. Acceso a la vía veredal por dos linderos. Apto para construcción de vivienda campestre. Cuenta con punto de agua veredal.','Lote de Terreno en Guatavita ','Guatavita','disponible'),(1,0,12860,'0048',21,'Terreno amplio y aprovechable para diversos proyectos. Acceso a la vía veredal. Cuenta con punto de agua veredal. Paisajes naturales y excelente ubicación.','Lote en Venta en Guatavita','Guatavita','disponible'),(1,0,12860,'0049',22,'Espacio ideal para construir una vivienda campestre. Apto para proyectos agrícolas o ganaderos. Acceso a vía veredal y punto de agua. Entorno natural con paisajes espectaculares. Ubicación estratégica cerca del casco urbano de Guatavita.','Lindo Lote en Guatavita con Vista Panorámica','Guatavita','disponible'),(1,0,19290,'0050',23,'Espacio amplio para construir vivienda campestre. Entorno natural privilegiado con hermosos paisajes. Acceso a vía veredal para fácil movilidad. Cuenta con punto de agua. Ubicación estratégica cerca de Guatavita y su oferta turística.','Hermosa Finca en Guatavita ','Guatavita','disponible'),(1,79,7500,'0051',24,'Vivienda campestre lista para habitar. Apta para finca de descanso, agricultura y ganadería. Hermosos paisajes naturales y aire puro. 1 nacimiento de agua propio. Servicios de energía eléctrica, punto de agua veredal y pozo séptico.','Linda Finca con Vivienda Campestre en Guatavita','Guatavita','disponible'),(1,0,180,'0052',25,'Ubicación estratégica: vista panorámica al embalse y al pueblo de Guatavita. Fácil acceso y cercanía a servicios esenciales. Zona con alta demanda para vivienda y comercio. Apto para múltiples usos: construcción de vivienda unifamiliar, bifamiliar o multifamiliar. Negocios como droguería, perfumería, papelería, almacenes y más. Infraestructura y accesibilidad: lote esquinero con entrada peatonal en piedra. Entorno tranquilo y seguro con gran potencial de crecimiento.','Lindo Lote en Guatavita con Vista al Embalse ','Guatavita','disponible'),(1,0,14500,'0054',26,'Infraestructura y comodidad: dos construcciones independientes. Garaje cubierto con capacidad para 2 vehículos. Salón de eventos, dos depósitos y un cuarto de herramientas. Puerta principal eléctrica. Espacios y ubicación privilegiada: cerca perimetral en piedra en el costado occidental. Colinda con la vía perimetral. Amplia zona verde. Ubicación estratégica: a pocos minutos del embalse de Tominé, en un entorno natural de alta valorización.','Finca con Dos Construcciones en Sesquilé ','Sesquilé','disponible'),(1,0,3800,'0055',27,'Infraestructura y comodidades: cocina equipada, baño completo. Amplia zona verde ideal para esparcimiento. Zona BBQ para reuniones y eventos. Chimenea para disfrutar del clima de montaña. Servicios disponibles: energía eléctrica, agua de nacimiento, pozo séptico. Potencial de uso y desarrollo: vivienda campestre para descanso y desconexión. Proyecto turístico: Glamping, camping, caminatas ecológicas, entre otros. Excelente ubicación para inversión en el sector turístico y recreativo.','Finca con Construcción y Vista al Embalse ','Guatavita','disponible'),(1,0,32000,'0056',28,'Entorno natural y vista privilegiada: hermosa panorámica al embalse de Tominé. Amplia zona verde con espacios ideales para conectar con la naturaleza. Servicios y comodidades: acueducto veredal, energía eléctrica, pozo séptico, vía de acceso veredal. Oportunidad de inversión: apto para proyectos de Glamping, Camping y Caminatas Ecológicas. Gran potencial turístico y de valorización en la región.','Finca con Construcción y Vista al Embalse en Guatavita ','Guatavita','disponible'),(1,0,7553,'0057',29,'Uso del suelo: ideal para actividades agropecuarias mecanizadas o altamente tecnificadas. Apto para proyectos forestales y construcción de vivienda campesina. Cuenta con vía de acceso veredal. Servicios adicionales: asesoría jurídica especializada. Ideal para: desarrollo de proyectos agrícolas y pecuarios, conservación y aprovechamiento forestal, inversión en finca raíz con alta valorización.','Lote Rural en Guasca','Guasca','disponible'),(1,72,17090,'0058',30,'Ubicación privilegiada: espectacular vista al Embalse de Tominé. Entorno natural rodeado de vegetación y tranquilidad. Acceso vehicular y peatonal. Comodidades y servicios: acueducto veredal, energía eléctrica, pozo séptico. Ideal para: casa de descanso en un entorno campestre. Proyecto de ecoturismo o inversión. Actividades agropecuarias.','Linda Finca con Vivienda en Sesquilé ','Sesquilé','disponible'),(1,0,215,'0059',31,'Diseño exclusivo y espacios amplios: sala con chimenea y techos de triple altura. Comedor independiente y cocina integral abierta. Recibidor y estudio o habitación con clóset. Baño social completo y patio espacioso con depósito y zona de lavado. Parqueadero doble: 1 cubierto y 1 descubierto. Confort en cada nivel: segundo nivel con hall de alcobas, habitación principal con walking closet, baño con jacuzzi y balcón, habitación auxiliar con baño privado, clóset y balcón. Tercer nivel con habitación auxiliar o estar de TV, amplio balcón y terraza con vista. Seguridad y acabados premium: sistema de alarma con monitoreo y cerca eléctrica. Iluminación natural y detalles arquitectónicos modernos.','Hermosa Casa en Chía ','Chía','disponible'),(1,140,10000,'0064',32,'Ubicación privilegiada: vista panorámica al embalse, rodeada de naturaleza. Entorno tranquilo, ideal para descanso, inversión o proyectos turísticos. Servicios y comodidades: agua de nacimiento y acueducto veredal. Energía eléctrica y pozo séptico.','Linda Finca en Sesquilé con Vista al Embalse','Sesquilé','disponible'),(1,180,590,'0065',33,'Ubicación estratégica: en el área urbana de Sesquilé, cerca de comercios, colegios y servicios esenciales. Fácil acceso a la vía principal hacia Bogotá y municipios cercanos. Espacio ideal para vivienda o inversión: amplio lote con potencial para futuras construcciones o ampliaciones. Casa con excelente distribución y diseño funcional. Servicios disponibles: acueducto y alcantarillado. Energía eléctrica.','Casa Lote Urbano en Sesquilé','Sesquilé','disponible'),(1,0,26000,'0066',34,'Entorno natural privilegiado: ideal como finca de descanso, rodeada de naturaleza y paisajes espectaculares. Ubicación estratégica con fácil acceso a Bogotá y municipios aledaños. Espacio ideal para turismo rural, ecoturismo o retiro campestre. Potencial productivo: apta para ganadería y agricultura. Suelo fértil con condiciones óptimas para diversos cultivos. Servicios disponibles: acueducto y alcantarillado. Energía eléctrica. Cuenta con servidumbre vehicular para acceso fácil.','Linda Finca en Guasca ','Guasca','disponible'),(1,0,25117,'0067',35,'Amplio terreno con uso versátil: perfecto para construir un proyecto campestre o turístico. Ubicación estratégica con potencial para actividades comerciales. Vistas inigualables al embalse de Tominé, ideales para un refugio de descanso o negocio eco-turístico. Servicios completos: acueducto y alcantarillado. Energía eléctrica. Pozo séptico para mayor autonomía.','Lote con Excelente Vista al Embalse en Guatavita','Guatavita','disponible'),(1,146.04,94.5,'0068',36,'Vivienda amplia y cómoda: casa de 2 niveles + altillo, con un diseño funcional y vistas espectaculares. 4 habitaciones para mayor comodidad. 4 baños, ideales para la familia y visitas. Estudio, perfecto para trabajo en casa o sala de lectura. Balcón con vista panorámica al embalse y al área urbana. Sala y comedor amplios, con excelente iluminación natural. Cocina con distribución eficiente. Área de ropas independiente. Accesibilidad y parqueaderos: garaje cubierto para 1 vehículo. Parqueadero externo adicional. Dos ingresos al inmueble, por el costado oriental y occidental. Vía de acceso en piedra, asegurando una entrada estable y de fácil mantenimiento. Servicios completos: acueducto y alcantarillado. Energía eléctrica e internet. Parabólica y gas natural.','Linda Casa en Venta con Vista al Embalse y Área Urbana de Guatavita','Guatavita','disponible'),(1,0,702.72,'0069',37,'Ubicación privilegiada: situado en el perímetro urbano, con acceso a servicios esenciales. Vista panorámica al embalse de Tominé, ideal para quienes buscan tranquilidad y naturaleza. Zona en alta valorización, perfecta para inversión o construcción de vivienda. Oportunidad de construcción: permite desarrollar una vivienda de dos niveles y altillo, ideal para una casa campestre moderna. Entorno exclusivo, perfecto para descanso o inversión en turismo rural.','Lote en Venta en el Perímetro Urbano de Guatavita','Guatavita','disponible'),(1,0,1500,'0071',38,'Ubicación privilegiada: sobre la vía principal, garantizando fácil acceso y conectividad. A pocos minutos del embalse de Tominé, un destino turístico de alto interés. Zona de alta valorización y exclusividad. Potencial de desarrollo: ideal para construir una vivienda campestre moderna y cómoda. Entorno natural, perfecto para descanso o inversión en turismo rural. Excelente alternativa para proyectos sostenibles y ecológicos.','Lote en Venta en Guatavita','Guatavita','disponible'),(1,400,1300,'0072',39,'Amplia y funcional distribución: 4 habitaciones, incluyendo una en el primer piso. Cuarto de servicio y área de ropas. 5 baños privados + 1 baño social. Sala en primer y segundo piso, ambas con espacios acogedores. Cocina independiente en cada nivel. Comedor amplio e iluminado. 3 accesos independientes al predio. Servicios disponibles: energía eléctrica. Acueducto veredal. Pozo séptico. Gas natural. Ubicación estratégica y ventajas del sector: espectacular vista al embalse de Tominé. Zona de alta valorización y exclusividad. Entorno natural ideal para descanso y recreación.','Casa Lote con Vista al Embalse ','Guatavita','disponible'),(1,0,22870,'0073',40,'Recursos hídricos propios: 3 nacederos de agua naturales. 2 reservorios, ideales para el abastecimiento hídrico. Construcciones existentes: 2 cabañas en excelente estado. Servicios disponibles: acueducto veredal. Energía eléctrica. Pozo séptico. Entrada vehicular, facilitando el acceso y movilidad. Ubicación y potencial: vista privilegiada al embalse de Tominé. Ideal para proyectos turísticos, vivienda campestre, agricultura o ganadería. Zona tranquila y con alta valorización.','Lote con Vista al Embalse en Venta','Guatavita','disponible'),(1,560,28700,'0074',41,'Vivienda amplia y moderna: 2 niveles con diseño campestre y elegante. 4 habitaciones con excelente iluminación. 3 baños privados y 2 baños sociales. Cocina tipo americana, ideal para compartir en familia. Sala con chimenea, perfecta para el clima de la región. Comedor independiente con vista panorámica. 2 estudios (uno en cada piso). 2 terrazas, una en cada nivel, para disfrutar del paisaje. Espacios exteriores y adicionales: parqueadero cubierto para 2 vehículos. Parqueadero al aire libre con capacidad para 6 vehículos. Depósito para almacenamiento. Zona verde con BBQ, ideal para reuniones y descanso. Servicios y autonomía hídrica: acueducto veredal y pozo séptico. Energía eléctrica e internet. TV satelital. 2 tanques de agua con capacidad total de 4.000 litros. Electrobomba de agua para garantizar suministro constante. Ubicación y potencial: colinda con vía veredal, facilitando el acceso. Ideal para finca de descanso, turismo rural, ganadería o agricultura.','Hermosa Finca Campestre en Venta ','Guatavita','disponible'),(1,60,29.567,'0075',42,'Infraestructura y servicios: vivienda campestre de 60 m² lista para habitar. Acueducto veredal, energía eléctrica y pozo séptico. Recursos hídricos: 1 nacedero de agua natural. 2 reservorios para almacenamiento y aprovechamiento hídrico. Potencial de uso: ganadería y agricultura, espacio para expansión y mejoras en la infraestructura. Entorno natural ideal para descanso y turismo rural. Ubicación y accesibilidad: colinda con vía veredal, facilitando el acceso al predio.','Hermosa Finca en Venta','Guatavita','disponible'),(1,0,15900,'0076',43,'Acceso vehicular directo. Viabilidad de acueducto veredal y energía eléctrica. Amplio espacio para actividades agrícolas y ganaderas. Entorno natural con paisajes espectaculares. ','Lote con Espectacular Paisaje en Venta','Guatavita','disponible'),(1,0,12300,'0077',44,'Ubicación estratégica: colinda con vía veredal, dos entradas al predio. Recursos hídricos disponibles: punto de agua veredal, agua de nacimiento. Usos ideales: construcción de vivienda campestre, actividades agrícolas y ganaderas, inversión en finca raíz.','Lote Rural en Venta en Guatavita','Guatavita','disponible'),(1,0,12600,'0078',45,'Terreno con acceso estratégico: colinda con vía veredal, fácil acceso para transporte de materiales y maquinaria. Servicios disponibles: punto de agua veredal. Usos ideales: construcción de vivienda campestre, actividades agrícolas y ganaderas, inversión en finca raíz.','Lote Rural en Venta en Guatavita ','Guatavita','disponible'),(1,0,10000,'0080',47,'Acceso vehicular por vía veredal. Punto de agua veredal disponible. Topografía variada con zonas planas y onduladas. Ideal para construcción de vivienda campestre, proyectos agrícolas o ganaderos. ','Lote en Venta en Guatavita','Guatavita','disponible'),(1,0,540,'0081',48,'Esta propiedad de 540 m² es ideal para inversión o vivienda familiar. Ubicada en el centro de Sesquilé, cuenta con múltiples espacios y servicios completos. 4 apartamentos independientes, 1 local comercial, 1 bodega amplia.\nServicios de acueducto, alcantarillado, energía, internet y parabólica Oportunidad única en una zona con alta valorización.','Excelente Ubicación a una Cuadra del Parque Principal De Sesquilé','Sesquilé','disponible'),(1,0,85.176,'0082',49,'Ubicación Privilegiada a 25 Minutos del Casco Urbano.\nEsta finca de 85.176 m² ofrece un entorno natural inigualable, ideal para descanso o proyectos agrícolas y ganaderos. Su terreno fértil y recursos hídricos la convierten en una excelente inversión. Vivienda campestre Acueducto veredal, energía eléctrica y pozo séptico, 3 nacimientos de agua y 1 reservorio.\nServidumbre privada con acceso a toda la finca.\nOpción perfecta para quienes buscan tranquilidad y contacto con la naturaleza.','Finca en Venta en Guatavita – Naturaleza y Amplio Terreno','Guatavita','disponible');
